def count_distinct_strings(s):
    if len(s) == 1:
        return 6  # The possible substrings: '', '*', 'a', 'b', 'c', 'ab'
    elif len(s) == 2:
        return 15  # The possible substrings: '', '*', 'a', 'b', 'c', 'a*', 'b*', 'ab', 'a*', 'b*', 'abc', 'a*b', 'b*c', '*b', '*c', 'abc'
    else:
        n = len(s)
        prefix = [1] * n  # All single-character strings are distinct
        for i in range(1, n):
            if s[i] == s[i-1]:
                prefix[i] = prefix[i-1]
            else:
                prefix[i] = prefix[i-1] + 1
        dp = [0] * n
        dp[0] = 1  # The empty string is distinct
        for i in range(1, n):
            dp[i] = dp[i-1] + prefix[i-1] * (n - i)
        ans = 1
        for c in set(s):
            temp_set = set()
            for i in range(n):
                sub = s[i+1:] if i == n else s[:i+1]
                temp_set.add(str(sub).replace(c, '*'))
            ans += len(temp_set)
        return ans + (n+1) * prefix[n-1]

