def is_password_possible(substrings):
    n = len(substrings)
    alphabet = set(i for word in substrings for i in word)
    set_alphabet = set(i for word in substrings for i in word if i.isdigit())

    # Check if all digits are unique in the password
    if len(set_alphabet) != len(set_alphabet.difference('0')):
        return False

    # Check if the maximum frequency of any character class is <= 3
    max_count = 0

    for i in alphabet:
        current_count = substrings.count(i)
        if i.isdigit():
            if current_count > max_count / 3:
                return False
            max_count = min(current_count, max_count)
        else:
            if current_count > (n-1) // 3:
                return False
            max_count = min(current_count, max_count)

    # Check if the sum of all frequency counts is divisible by 3
    if sum([a + b + c for a, b, c in substrings]) % 3 != 0:
        return False

    return True

