from collections import deque

def max_cyclical_shifts(brackets):
    n = len(brackets)
    max_beauty = 0
    dp = [0] * n
    stack = deque()

    for i in range(n):
        while stack and (brackets[stack[-1]] not in ('(', '[')):
            stack.pop()
        if stack:
            dp[i] = (i - stack[-1]) // 2
        stack.append(i)

    for i in range(n - 1, 0, -1):
        while stack and brackets[stack[-1]] not in ('(', '['):
            stack.pop()
        if stack:
            dp[i - 1] = max(dp[i - 1], (i - stack[-1]) // 2)

    for j in range(1, n):
        dp[j] = max(dp[j], dp[j-1])

    for i in range(n - 1, 0, -1):
        while stack and brackets[stack[-1]] not in ('(', '['):
            stack.pop()
        if stack:
            dp[i - 1] = max(dp[i - 1], (n - 1 - stack[-1]) // 2)

    l = r = 0
    for i in range(n - 1):
        if dp[i] > max_beauty:
            max_beauty = dp[i]
            l = i + 1
            r = i + 2

    return max_beauty, l, r

