from collections import defaultdict
from functools import lru_cache

def distinct_strings_count(s):
    n = len(s)
    memo = defaultdict(set)

    @lru_cache(None)
    def rec(index, component):
        if index < 0:
            return 1
        total = 0
        for i in range(index + 1):
            if s[index] == s[i]:
                total += rec(index - i, component | {s[index]})
        return total

    result = set()
    for i in range(1, n + 1):
        for j in range(i):
            rec_result = rec(j, set()) - {s[j]}
            if s[j] != '*':
                rec_result -= {s[j] + '*'}
            memo[i].update(map(tuple, result))
            result.update({s[:j] + (i,) + s[j:] for i in rec_result if (i != '*' or j > 0) or (i == '*' and s[:j]) in (w := list(w) for w in memo[j] if ''.join(w) in memo[j]) and tuple(sorted(w)) in memo[j]})

    return len(result)

