from typing import List

def calculate_area_polygon(x_points: List[tuple]) -> float:
    delta, total_area = 0, 0.0
    for i in range(len(x_points)):
        x_vertex, y_vertex = x_points[i]
        if i > 0 and i < len(x_points) - 1:
            x_next, _ = x_points[(i + 1) % len(x_points)]
            total_area += delta * (x_vertex + x_next) * (abs(x_vertex - x_next) / 2)
            delta = 0
        if i == 0:
            total_area += x_vertex * (y_vertex + y_points[i + 1])
        elif i == len(x_points) - 1:
            total_area += x_vertex * (y_vertex + y_points[i - 1])
        else:
            delta += (x_vertex + x_next) / 2
    return abs(total_area + abs(delta * y_vertex) / 2)

