import math

def can_organize_pages(n, k, x, y):
    total_tables = sum(x)
    total_formulas = sum(y)
    if (total_tables * k < len(x) or total_formulas * k < len(y)):
        return "NO"

    last_pages = math.ceil(total_tables / k)

    if last_pages >= n:
        if last_pages >= len(x):
            return "YES"
        return "NO"

    neighbor_strongtables = 0
    neighbor_strongformulas = 0

    for i in range(n):
        strong_tables = x[i] - k + 1
        strong_formulas = y[i] - k + 1

        extra_tables, extra_formulas = total_tables - x[i], total_formulas - y[i]

        if neighbor_strongtables+strong_tables < i and neighbor_strongformulas+strong_formulas < i:
            if extra_tables + strong_tables < k:
                neighbor_strongtables += strong_tables
                neighbor_strongformulas += strong_formulas

            if neighbor_strongtables+k < last_pages and neighbor_strongformulas+k < last_pages:
                return "YES"
            else:
                return "NO"

    if neighbor_strongtables+k < last_pages and neighbor_strongformulas+k < last_pages:
        return "YES"
    else:
        return "NO"

