from collections import deque

def solve(n, s):
    dp = [0] * n
    for i in range(n - 2, -1, -1):
        if s[i] != s[n - i - 1] and i <= n // 2:
            dp[i] = max(dp[i + 1], dp[i + len(s) // 2])
        elif i <= n // 2:
            dp[i] = max(dp[i + 1], dp[i + len(s) // 2])

    swaps = []
    vis = [0] * n
    stack = deque([0])
    while stack:
        i = stack.pop()
        if vis[i] == 1 or dp[i] == dp[i + 1]:
            continue
        vis[i] = 1
        for j in range(n):
            if vis[j] == 1:
                continue
            dp2 = dp[:]
            if s[i] != s[n - j - 1]:
                dp2[i] = max(dp2[i + 1], dp2[i + len(s) // 2])
            if j <= n // 2:
                dp2[i] = max(dp2[i + 1], dp2[i + len(s) // 2])
            if dp2[i] > dp2[i + 1] or dp2[i] < dp2[i + 1]:
                stack.append(i - len(s) // 2 + j)
        swaps.append((i - len(s) // 2, j))

    m = max(dp)
    ans = -1
    l = r = -1
    for i, j in swaps:
        if m == dp[i]:
            l = i
            r = j
            break
    return m, l + 1, r + 1

