def backtrack(remaining, used):
    if not remaining:
        return True

    for i in range(len(remaining) - 2):
        substring = remaining[i:i+3]
        for j in range(used + 1):
            if not used[j] and is_valid(substring):
                decoded.append(substring)
                used[j] += 1
                if backtrack(remaining[i+3:], used):
                    return True
                used[j] -= 1
    return False

def is_valid(s):
