from math import comb

def count_valid_subsets(N):
    dp = [[0] * (N + 1) for _ in range(N + 1)]
    dp[0][0] = 1  # An empty subset is considered a valid subset

    for i in range(1, N + 1):
        dp[i][i] = 1  # Each number forms a subset of itself
        dp[i][0] = custom_binomial_coeff(i)  # All 0's in the first position form valid subsets

    for length in range(2, N + 1):
        for parity in range(0, N + 1):
            if parity % 2 == 0:  # Even parity
                dp[parity][length] = dp[parity][length - 2]
            else:
                dp[parity][length] = dp[parity][length - 1]

    return dp[0][N - 1]

def custom_binomial_coeff(n):
    if n == 0:
        return 1
    return comb(n, 2) + custom_binomial_coeff(n - 1)

# Example usage
N = 4
print(count_valid_subsets(N))  # Output the number of valid subsets for input N
