def count_valid_subsets(n):
    if n == 1:
        return 2  # {, 1}
    if n == 2:
        return 4  # {}, {1}, {2}, {1, 2}
    if n == 3:
        return 8  # {}, {1}, {2}, {3}, {1, 2}, {1, 3}, {2, 3}, {1, 2, 3}
    if n == 4:
        return 16  # Total 16 subsets, out of which 2 subsets contain bad tuples (1, 2, 4) and (1, 2, 3, 4)
    # For n > 4, we can observe that the number of valid subsets is given by 2^n - 2
    return 2**n - 2

